export function photosFor(exerciseId: string): ExImage | undefined {
  const entry = EX_IMAGES[exerciseId];
  return entry ? { ...entry, images: entry.images.map((_, index) => `/media/exercises/${exerciseId}-${index}.jpg`) } : undefined;
}
